<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $names @var string $name @var string $from @var string $to @var ?array $t @var bool $canExport */
require __DIR__ . '/_nav.php'; $money = \SysferaStoragerent\Reports::MONEY; ?>
<form class="sr-filter" method="get" action="<?= e($sf->url('/reports')) ?>"><select name="r"><?php foreach ($names as $n): ?><option value="<?= e($n) ?>"<?= $n === $name ? ' selected' : '' ?>><?= e($sf->t('rep_' . $n)) ?></option><?php endforeach; ?></select>
  <input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn primary"><?= e($sf->t('rep_run')) ?></button></form>
<?php if ($t): $q = 'r=' . urlencode($name) . '&from=' . urlencode($from) . '&to=' . urlencode($to); ?>
<div class="card"><div class="row sr-between"><h3 style="margin:0"><?= e($sf->t('rep_' . $name)) ?></h3>
  <?php if ($canExport): ?><span><a class="btn sm" href="<?= e($sf->url('/reports/export?' . $q . '&fmt=xlsx')) ?>">XLSX</a> <a class="btn sm" href="<?= e($sf->url('/reports/export?' . $q . '&fmt=csv')) ?>">CSV</a> <a class="btn sm" target="_blank" href="<?= e($sf->url('/reports/export?' . $q . '&fmt=print')) ?>"><?= e($sf->t('print_pdf')) ?></a></span><?php endif; ?></div>
<?php if (!empty($t['buckets'])): ?><p><?php foreach ($t['buckets'] as $b => $v): ?><span class="badge <?= $b === 'current' ? 'mute' : ($b === '1-30' ? 'warn' : 'bad') ?>"><?= e($sf->t('bucket_' . $b)) ?>: <?= e(sr_m($v, $lang)) ?></span> <?php endforeach; ?></p><?php endif; ?>
<?php if (!$t['rows']): ?><p class="muted"><?= e($sf->t('none')) ?></p><?php else: ?><div class="sr-scroll"><table><thead><tr><?php foreach ($t['cols'] as $c): ?><th class="<?= in_array($c, $money, true) ? 'r' : '' ?>"><?= e($sf->t('col_' . $c)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach ($t['rows'] as $r): ?><tr><?php foreach ($t['cols'] as $c): $v = $r[$c]; ?><td class="<?= in_array($c, $money, true) ? 'r' : '' ?>"><?php
  if (in_array($c, $money, true)) echo e(sr_m($v, $lang)); elseif ($c === 'due_date') echo e(sr_d((string)$v)); elseif ($c === 'status') echo e($sf->t('st_' . $v)); elseif ($c === 'bucket') echo e($sf->t('bucket_' . $v)); else echo e(is_float($v) ? sr_num($v) : (string)$v); ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody>
<?php if ($t['sum']): ?><tfoot><tr><?php foreach ($t['cols'] as $i => $c): ?><td class="<?= isset($t['sum'][$c]) ? 'r' : '' ?>"><b><?= $i === 0 ? e($sf->t('total')) : (isset($t['sum'][$c]) ? e(sr_m($t['sum'][$c], $lang)) : '') ?></b></td><?php endforeach; ?></tr></tfoot><?php endif; ?></table></div><?php endif; ?></div>
<?php else: ?><div class="card empty"><?= e($sf->t('rep_pick')) ?></div><?php endif; ?>
